#![cfg(feature = "logger")]

//! JSON-visible source contract, generated by executing the current TypeScript.
//! Sink ordering, error reporting and stronger random IDs intentionally differ.
use std::sync::{Arc, Mutex};

use dima_rust::utils::logger::{
    CacheRecord, CacheSink, Clock, ConsoleRecord, ConsoleSink, ConsoleStream, Destination,
    IdSource, Level, LogOptions, Logger, LoggerConfig, MetadataRecord, MetadataSink, OtelRecord,
    OtelSink, SinkFuture, SinkHandles,
};
use serde_json::{Value, json};

#[derive(Default)]
struct Capture {
    cache: Mutex<Vec<CacheRecord>>,
    console: Mutex<Vec<ConsoleRecord>>,
    metadata: Mutex<Vec<MetadataRecord>>,
    otel: Mutex<Vec<OtelRecord>>,
}
impl CacheSink for Capture {
    fn store(&self, record: CacheRecord) -> SinkFuture<'_> {
        Box::pin(async move {
            self.cache.lock().unwrap().push(record);
            Ok(())
        })
    }
}
impl ConsoleSink for Capture {
    fn write(&self, record: ConsoleRecord) -> SinkFuture<'_> {
        Box::pin(async move {
            self.console.lock().unwrap().push(record);
            Ok(())
        })
    }
}
impl MetadataSink for Capture {
    fn record(&self, record: MetadataRecord) -> SinkFuture<'_> {
        Box::pin(async move {
            self.metadata.lock().unwrap().push(record);
            Ok(())
        })
    }
}
impl OtelSink for Capture {
    fn emit(&self, record: OtelRecord) -> SinkFuture<'_> {
        Box::pin(async move {
            self.otel.lock().unwrap().push(record);
            Ok(())
        })
    }
}
struct FixedClock(i64);
impl Clock for FixedClock {
    fn now_millis(&self) -> i64 {
        self.0
    }
}
struct FixedId;
impl IdSource for FixedId {
    fn next_id(&self) -> String {
        "source-fixture".into()
    }
}

#[tokio::test]
async fn matches_actual_typescript_json_contract() {
    let corpus: Value = serde_json::from_str(include_str!("fixtures/logger_parity.json")).unwrap();
    for case in corpus["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];
        let expected = &case["expected"];
        let level = match input["level"].as_str().unwrap() {
            "trace" => Level::Trace,
            "debug" => Level::Debug,
            "info" => Level::Info,
            "warn" => Level::Warn,
            "error" => Level::Error,
            "fatal" => Level::Fatal,
            _ => unreachable!(),
        };
        let options = LogOptions {
            destination: match input["options"]["destination"].as_str() {
                Some("cache") => Destination::Cache,
                Some("console") => Destination::Console,
                _ => Destination::Both,
            },
            platform: input["options"]["platform"].as_str().map(str::to_owned),
            channel_id: input["options"]["channelId"].as_str().map(str::to_owned),
            ..Default::default()
        };
        let capture = Arc::new(Capture::default());
        let logger = Logger::new(
            LoggerConfig::default(),
            SinkHandles {
                cache: Some(capture.clone()),
                console: Some(capture.clone()),
                metadata: Some(capture.clone()),
                otel: Some(capture.clone()),
            },
            Arc::new(FixedClock(input["at"].as_i64().unwrap())),
            Arc::new(FixedId),
        )
        .unwrap();
        let report = logger.log(level, input["data"].clone(), options).await;
        assert!(report.success(), "{name}: {report:?}");
        let writes: Vec<Value> = capture
            .cache
            .lock()
            .unwrap()
            .iter()
            .map(|record| {
                json!({
                    "keyPrefix": format!("{}:", record.key.rsplit_once(':').unwrap().0),
                    "entry": serde_json::from_str::<Value>(&record.json).unwrap(),
                    "ttlSeconds": record.ttl_seconds,
                })
            })
            .collect();
        assert_eq!(json!(writes), expected["writes"], "{name}: cache");
        let console: Vec<Value> = capture.console.lock().unwrap().iter().map(|record| json!({
            "stream": if record.stream == ConsoleStream::Stdout { "stdout" } else { "stderr" },
            "output": serde_json::from_str::<Value>(&record.json).unwrap(),
        })).collect();
        assert_eq!(json!(console), expected["console"], "{name}: console");
        assert_eq!(
            serde_json::to_value(&*capture.metadata.lock().unwrap()).unwrap(),
            expected["metadata"],
            "{name}: metadata"
        );
        let records = capture.otel.lock().unwrap();
        assert_eq!(
            records.len(),
            expected["otel"].as_array().unwrap().len(),
            "{name}: OTEL count"
        );
        for (record, source) in records.iter().zip(expected["otel"].as_array().unwrap()) {
            assert_eq!(
                record.level.as_str(),
                source["severityText"],
                "{name}: OTEL severity"
            );
            assert_eq!(
                serde_json::from_str::<Value>(&record.body_json).unwrap(),
                source["body"],
                "{name}: OTEL body"
            );
        }
    }
}
